 def __bool__(self):
  events.append('truth')
  return True
class Source:
 def __iter__(self):
  events.append('iter')
  return iter([-2,3])
try:
 result=('ok', list(map(**{Key('strict'): Strict()})))
except Exception as e:
 result=(type(e).__name__, str(e))
result=(result,events)

